(function () {
  const state = {
    registry: null, page: 1, pageSize: 25, query: '', type: '', searchTimer: null,
    lines: [], files: [], editingDocument: null, selected: null, previewUrl: '', deleteTask: null,
    voucher: null, voucherDirty: false, voucherLines: [], voucherCandidates: [], voucherMeta: null,
    people: { givers: [], receivers: [] }, personRole: 'giver', personEditing: null,
    exportFormat: 'xlsx', exportPeriod: 'current_month', exportBusy: false,
  };
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;' })[char]);
  const money = value => `${new Intl.NumberFormat('ro-RO',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value||0))} lei`;
  const qty = value => new Intl.NumberFormat('ro-RO',{minimumFractionDigits:0,maximumFractionDigits:4}).format(Number(value||0));
  const today = () => new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Bucharest'});
  const toast = (message,type='success') => window.BUSINESS_UI?.showToast?.(message,type);
  const icon = name => {
    const paths={box:'m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5m-9 5v9M7.5 5.5l9 5',document:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6m-6 4h6',download:'M12 3v12m0 0 4-4m-4 4-4-4M5 17v4h14v-4',table:'M4 4h16v16H4zM4 10h16M10 4v16',check:'m5 12 4 4L19 6',archive:'M4 4h16v5H4zM6 9v11h12V9m-8 4h4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8M19 8v6m3-3h-6',receipt:'M6 2h12v20l-3-2-3 2-3-2-3 2V2Zm3 6h6m-6 4h6m-6 4h4',chart:'M4 20h16M7 16v-4m5 4V8m5 8V4'};
    return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.document}"/></svg>`;
  };
  const open = id => { const el=$(id); if(!el)return; el.hidden=false; requestAnimationFrame(()=>el.classList.add('visible')); };
  const close = id => { const el=$(id); if(!el)return; el.classList.remove('visible'); setTimeout(()=>{if(!el.classList.contains('visible'))el.hidden=true;},180); };
  const docNumber = item => trimJoin(item.series,item.document_number);
  const voucherNumber = item => trimJoin(item.series,item.voucher_number);
  const trimJoin = (...values) => values.map(value=>String(value||'').trim()).filter(Boolean).join(' ') || '—';
  const typeLabel = type => ({factura:'Factură',bon:'Bon',pv:'Proces-verbal'}[type]||type||'Document');
  const dateLabel = value => String(value||'').split('-').reverse().join('.');
  const saveDownload = file => { const bytes=Uint8Array.from(atob(file.content_base64),char=>char.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:file.mime_type}));const link=document.createElement('a');link.href=url;link.download=file.file_name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1200); };
  const filePayload = file => new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error(`Fișierul ${file.name} nu a putut fi citit.`));reader.onload=()=>resolve({file_name:file.name,mime_type:file.type||'application/octet-stream',content_base64:String(reader.result).split(',').pop()});reader.readAsDataURL(file);});

  function page(title='Consumabile') {
    return `<div class="shop-commerce-page shop-fixed-assets-page shop-consumables-page"><nav class="shop-fixed-assets-breadcrumb"><button type="button" data-shop-open="shop-fixed-assets">${icon('box')}<span>Gestiune mijloace fixe</span></button><span>/</span><strong>Consumabile</strong></nav><header class="shop-commerce-head shop-fixed-assets-head" data-commerce-kind="consumables"><div class="shop-fixed-assets-heading"><span class="shop-fixed-assets-heading-icon">${icon('archive')}</span><div class="shop-commerce-title"><span>GESTIUNE ȘI CONSUM</span><h1>${esc(title)}</h1><p>Documente de intrare, stoc disponibil și bonuri de consum.</p></div></div><div class="shop-commerce-head-actions"><button type="button" class="shop-commerce-refresh" id="shop-consumables-refresh" title="Actualizează">${refreshIcon()}</button><button type="button" class="shop-commerce-add" id="shop-consumables-add"><span class="shop-fixed-assets-add-symbol">${plusIcon()}</span><span>Înregistrează document</span><svg class="shop-fixed-assets-add-arrow" viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></button></div></header><main id="shop-consumables-content" class="shop-commerce-content"><div class="shop-commerce-loading">Se încarcă...</div></main></div>`;
  }
  const refreshIcon=()=>'<svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 0 2 5M20 4v7h-7"/></svg>';
  const plusIcon=()=>'<svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg>';
  const closeButton=id=>`<button type="button" aria-label="Închide" data-consumables-close="${id}">×</button>`;

  function modals() {
    return `${documentModal()}${detailModal()}${voucherModal()}${peopleModal()}${confirmModal()}${exportModal()}`;
  }
  function section(number,title,text){return `<div class="shop-editor-section"><b>${number}</b><span><strong>${title}</strong><small>${text}</small></span></div>`;}
  function documentModal(){return `<div class="shop-commerce-overlay shop-fixed-asset-overlay" id="shop-consumable-create-modal" hidden><form class="shop-commerce-modal shop-fixed-asset-create" id="shop-consumable-create-form"><header class="shop-fixed-asset-create-head"><span class="shop-fixed-asset-create-icon">${icon('document')}</span><div class="shop-fixed-asset-create-title"><small>GESTIUNE CONSUMABILE</small><h2 id="shop-consumable-editor-title">Înregistrează un document</h2><p>Adaugă documentul justificativ și consumabilele intrate în gestiune.</p></div><div class="shop-fixed-asset-create-progress"><span class="active"><b>1</b>Document</span><i></i><span><b>2</b>Poziții</span></div>${closeButton('shop-consumable-create-modal')}</header><div class="shop-commerce-modal-scroll shop-fixed-asset-create-body"><section class="shop-fixed-asset-form-card document">${section('01','Document justificativ','Factură, bon sau proces-verbal, împreună cu toate fișierele originale.')}<div class="shop-commerce-columns three shop-fixed-asset-document-fields"><label>Data documentului *<input id="shop-consumable-document-date" type="date" required></label><label>Tip document *<select id="shop-consumable-document-type"><option value="factura">Factură</option><option value="bon">Bon</option><option value="pv">Proces-verbal</option></select></label><label>Serie / număr *<span class="shop-fixed-asset-series-number"><input id="shop-consumable-series" maxlength="80" placeholder="Serie"><input id="shop-consumable-number" maxlength="120" placeholder="Număr" required></span></label></div><label class="shop-fixed-asset-notes">Observații <em>opțional</em><textarea id="shop-consumable-notes" rows="2" maxlength="2000"></textarea></label><button type="button" class="shop-fixed-asset-file" id="shop-consumable-file-pick"><span>${icon('download')}</span><b>Atașează documentele originale</b><small>PDF, imagine, Excel, Word sau XML · maximum 15 MB / fișier</small><i>Alege fișiere</i></button><input id="shop-consumable-file-input" type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.webp,.xls,.xlsx,.doc,.docx,.xml" hidden><div id="shop-consumable-pending-files" class="shop-fixed-asset-file-list"></div></section><section class="shop-fixed-asset-form-card positions"><div class="shop-fixed-asset-position-intro">${section('02','Pozițiile documentului','Adaugă fiecare consumabil; valorile și TVA-ul se calculează automat.')}<div class="shop-fixed-asset-lines-head"><strong>CONSUMABILE</strong><button type="button" id="shop-consumable-add-line"><span>＋</span> Adaugă poziție</button></div></div><div id="shop-consumable-lines" class="shop-fixed-asset-lines"></div></section></div><footer class="shop-fixed-asset-create-footer"><p><span>✓</span>Stocul intră în gestiune după salvare.</p><div><button type="button" class="shop-fixed-asset-danger" id="shop-consumable-delete-document" hidden>Șterge documentul</button><button type="button" class="btn-ghost" data-consumables-close="shop-consumable-create-modal">Renunță</button><button type="submit" class="btn-primary" id="shop-consumable-save"><span>Înregistrează documentul</span></button></div></footer></form></div>`;}
  function detailModal(){return `<div class="shop-commerce-overlay shop-fixed-asset-overlay" id="shop-consumable-detail-modal" hidden><section class="shop-commerce-modal shop-fixed-asset-detail"><header><span class="shop-fixed-asset-modal-symbol">${icon('archive')}</span><div><small>FIȘĂ CONSUMABIL</small><h2 id="shop-consumable-detail-title">Consumabil</h2></div>${closeButton('shop-consumable-detail-modal')}</header><div class="shop-commerce-modal-scroll" id="shop-consumable-detail-content"></div><footer><button type="button" class="shop-fixed-asset-danger" id="shop-consumable-delete">Șterge consumabilul</button><button type="button" class="btn-primary" id="shop-consumable-edit">Editează documentul</button><button type="button" class="btn-ghost" data-consumables-close="shop-consumable-detail-modal">Închide</button></footer></section></div>`;}
  function voucherModal(){
    const party=(role,label,plural)=>`<div class="shop-consumption-party"><div class="shop-consumption-party-head"><label for="shop-consumption-${role}">${label} *</label><button type="button" data-manage-consumable-people="${role}">${icon('users')}<span>Administrează ${plural}</span></button></div><select id="shop-consumption-${role}" aria-label="${label}"></select><input id="shop-consumption-${role}-name" maxlength="240" placeholder="Numele ${role==='giver'?'predătorului':'primitorului'}" aria-label="${label} introdus manual"></div>`;
    return `<div class="shop-commerce-overlay shop-fixed-asset-overlay" id="shop-consumption-voucher-modal" hidden><form class="shop-commerce-modal shop-consumption-voucher" id="shop-consumption-voucher-form">
      <header><span class="shop-fixed-asset-modal-symbol">${icon('receipt')}</span><div><small>BON DE CONSUM COLECTIV</small><h2 id="shop-consumption-voucher-title">Bon de consum nou</h2><p>Înregistrează consumul și actualizează stocul disponibil.</p></div>${closeButton('shop-consumption-voucher-modal')}</header>
      <div class="shop-commerce-modal-scroll">
        <div class="shop-consumption-export-actions" id="shop-consumption-export-actions" hidden><div><strong>Descarcă bonul individual</strong><small id="shop-consumption-export-hint">Versiunea salvată a bonului</small></div><button type="button" data-consumption-export-format="pdf">${icon('document')} PDF</button><button type="button" data-consumption-export-format="xlsx">${icon('table')} Excel</button></div>
        <section class="shop-consumption-voucher-card">${section('01','Datele bonului','Următorul număr al seriei este completat automat.')}<div class="shop-commerce-columns three"><label>Data bonului *<input id="shop-consumption-voucher-date" type="date" required></label><label>Serie *<input id="shop-consumption-voucher-series" value="BC" maxlength="80" required></label><label>Număr *<input id="shop-consumption-voucher-number" maxlength="120" required></label></div><div class="shop-consumption-references"><label>Produs / lucrare (comandă) <em>Opțional</em><input id="shop-consumption-work-reference" maxlength="240" placeholder="Ex.: Revizie echipamente atelier"></label><label>Nr. comandă / cod produs <em>Opțional</em><input id="shop-consumption-order-reference" maxlength="240" placeholder="Ex.: COM-104 / cod intern"></label></div></section>
        <section class="shop-consumption-voucher-card">${section('02','Predare și primire','Selectează o persoană salvată sau introdu numele manual.')}<div class="shop-consumption-parties">${party('giver','Predător','predătorii')}${party('receiver','Primitor','primitorii')}</div></section>
        <section class="shop-consumption-voucher-card"><div class="shop-consumption-lines-heading">${section('03','Consumabile eliberate','Cantitățile pozitive se scad din stoc la salvare.')}<button type="button" id="shop-consumption-add-line">${plusIcon()} Adaugă consumabil</button></div><div id="shop-consumption-voucher-lines" class="shop-consumption-voucher-lines"></div></section>
        <label class="shop-consumption-notes"><span>Observații <em>Opțional</em></span><textarea id="shop-consumption-voucher-notes" rows="2" maxlength="2000" placeholder="Detalii despre utilizare, lucrare sau destinația consumabilelor"></textarea></label>
      </div><footer><button type="button" class="shop-fixed-asset-danger" id="shop-consumption-voucher-delete" hidden>Șterge bonul</button><button type="button" class="btn-ghost" data-consumables-close="shop-consumption-voucher-modal">Renunță</button><button type="submit" class="btn-primary" id="shop-consumption-voucher-save">Salvează bonul și scade stocul</button></footer></form></div>`;
  }
  function peopleModal(){return `<div class="shop-commerce-overlay shop-fixed-asset-overlay" id="shop-consumable-people-modal" hidden><section class="shop-commerce-modal shop-consumable-people"><header><span class="shop-fixed-asset-modal-symbol">${icon('users')}</span><div><small>DIRECTOR PERSOANE</small><h2 id="shop-consumable-people-title">Gestionari și primitori</h2></div>${closeButton('shop-consumable-people-modal')}</header><div class="shop-commerce-modal-scroll"><div class="shop-consumable-people-tabs"><button type="button" data-people-role="giver" class="active">Predători / gestionari</button><button type="button" data-people-role="receiver">Primitori</button></div><div class="shop-consumable-people-layout"><div id="shop-consumable-people-list"></div><form id="shop-consumable-person-form"><input id="shop-consumable-person-id" type="hidden"><label>Nume *<input id="shop-consumable-person-name" maxlength="240" required></label><label>Funcție / detalii<input id="shop-consumable-person-details" maxlength="500" placeholder="Ex: gestionar atelier"></label><label class="shop-consumable-person-active"><input id="shop-consumable-person-active" type="checkbox" checked><span>Persoană activă</span></label><div><button type="button" class="btn-ghost" id="shop-consumable-person-reset">Persoană nouă</button><button type="submit" class="btn-primary">Salvează</button></div></form></div></div><footer><button type="button" class="btn-primary" data-consumables-close="shop-consumable-people-modal">Gata</button></footer></section></div>`;}
  function confirmModal(){return `<div class="shop-commerce-overlay shop-fixed-asset-overlay" id="shop-consumable-confirm-modal" hidden><section class="shop-commerce-modal mini shop-fixed-asset-confirm"><header><span class="shop-fixed-asset-modal-symbol disposal">${icon('archive')}</span><div><small>CONFIRMARE</small><h2 id="shop-consumable-confirm-title">Confirmă operațiunea</h2></div>${closeButton('shop-consumable-confirm-modal')}</header><div class="shop-commerce-modal-scroll"><p id="shop-consumable-confirm-text"></p><p class="shop-fixed-asset-confirm-error" id="shop-consumable-confirm-error" hidden></p></div><footer><button type="button" class="btn-ghost" data-consumables-close="shop-consumable-confirm-modal">Renunță</button><button type="button" class="shop-fixed-asset-danger" id="shop-consumable-confirm-submit">Continuă</button></footer></section></div>`;}
  function exportModal(){const periods=[['all','Toată perioada','Întregul istoric'],['year','Tot anul','De la 1 ianuarie'],['six_months','6 luni','Ultimele șase luni'],['three_months','3 luni','Ultimele trei luni'],['last_month','Luna trecută','Luna calendaristică anterioară'],['current_month','Luna curentă','De la începutul lunii'],['custom','Custom','Interval ales de tine']].map(([value,label,hint])=>`<button type="button" data-consumables-period="${value}" class="${value==='current_month'?'active':''}"><span class="shop-nir-period-icon">${icon('document')}</span><strong>${label}</strong><small>${hint}</small><i></i></button>`).join('');return `<div class="shop-commerce-overlay shop-nir-registry-download-overlay shop-consumables-export" id="shop-consumables-export-modal" hidden><form class="shop-nir-registry-download-dialog" id="shop-consumables-export-form"><header><span class="shop-nir-registry-download-orb">${icon('download')}</span><div><small>EXPORT CONSUMABILE</small><h2>Exportă gestiunea și bonurile</h2><p>Excelul conține foi separate pentru stoc și bonurile de consum.</p></div>${closeButton('shop-consumables-export-modal')}</header><div class="shop-nir-registry-download-body"><section><div class="shop-nir-registry-section-title"><span>01</span><div><strong>Formatul exportului</strong><small>PDF, Excel sau arhivă completă cu documentele încărcate.</small></div></div><div class="shop-nir-registry-content-options"><button type="button" data-consumables-format="pdf">${icon('document')}<span><strong>PDF</strong><small>Gestiune și bonuri pentru tipărire</small></span><i></i></button><button type="button" data-consumables-format="xlsx" class="active">${icon('table')}<span><strong>Excel</strong><small>Foi „Consumabile” și „Bonuri de consum”</small></span><i></i></button><button type="button" data-consumables-format="zip">${icon('archive')}<span><strong>ZIP complet</strong><small>PDF + Excel + documentele justificative</small></span><i></i></button></div></section><section><div class="shop-nir-registry-section-title"><span>02</span><div><strong>Pentru ce perioadă?</strong><small>Alege rapid sau setează un interval exact.</small></div></div><div class="shop-nir-registry-periods">${periods}</div><div class="shop-nir-registry-custom" id="shop-consumables-export-custom" hidden><label>De la<input type="date" id="shop-consumables-export-from"></label><span>—</span><label>Până la<input type="date" id="shop-consumables-export-to"></label></div></section><aside class="shop-nir-registry-download-summary"><span>${icon('check')}</span><div><small>SE VA GENERA</small><strong id="shop-consumables-export-summary"></strong><p id="shop-consumables-export-range"></p></div></aside></div><footer><button type="button" class="btn-ghost" data-consumables-close="shop-consumables-export-modal">Renunță</button><button type="submit" class="shop-nir-registry-download-confirm" id="shop-consumables-export-confirm">${icon('download')}<span>Descarcă Excel</span></button></footer></form></div>`;}

  function overview(registry,items){const sum=key=>items.reduce((total,item)=>total+Number(item[key]||0),0);return `<section class="shop-fixed-assets-overview"><div class="shop-fixed-assets-overview-value"><div class="shop-fixed-assets-overview-total"><span class="shop-fixed-assets-overview-label">${icon('chart')}Valoarea paginii</span><p><strong>${new Intl.NumberFormat('ro-RO',{minimumFractionDigits:2,maximumFractionDigits:2}).format(sum('total_value'))}</strong><span>lei<small>TVA inclus</small></span></p></div><dl class="shop-fixed-assets-overview-breakdown"><div><dt>Stoc intrat</dt><dd>${qty(sum('quantity'))}</dd></div><div><dt>Stoc actual</dt><dd>${qty(sum('remaining_quantity'))}</dd></div></dl></div><dl class="shop-fixed-assets-overview-counts"><div><dt>Poziții în gestiune</dt><dd>${qty(registry.total)}</dd></div><div><dt>Cu bonuri de consum<small>Pe pagina curentă</small></dt><dd class="${items.some(i=>Number(i.consumption_count)>0)?'has-disposals':'no-disposals'}">${qty(items.filter(i=>Number(i.consumption_count)>0).length)}</dd></div></dl></section>`;}
  function pagination(registry,where){const page=Number(registry.page||1),count=Number(registry.page_count||1);return `<nav class="shop-order-table-top-pagination" aria-label="Paginare consumabile ${where}"><label><span>Pagina</span><input type="number" min="1" max="${count}" value="${page}" data-consumables-page-input><em>/ ${count}</em></label><button type="button" data-consumables-page="${page-1}" ${page<=1?'disabled':''}>‹</button><button type="button" data-consumables-page="${page+1}" ${page>=count?'disabled':''}>›</button></nav>`;}
  function toolbar(registry){const total=Number(registry.total||0),first=total?(registry.page-1)*registry.page_size+1:0,last=Math.min(total,registry.page*registry.page_size);return `<section class="shop-fixed-assets-toolbar"><div class="shop-fixed-assets-controls"><label class="shop-fixed-assets-search-field"><svg viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/></svg><input id="shop-consumables-search" type="search" value="${esc(state.query)}" placeholder="Caută semantic după consumabil, serie sau document…"></label><label class="shop-fixed-assets-filter-field"><span class="shop-fixed-assets-filter-symbol">${icon('document')}</span><span class="shop-fixed-assets-filter-caption">Tip document</span><select id="shop-consumables-type"><option value="">Toate documentele</option><option value="factura" ${state.type==='factura'?'selected':''}>Facturi</option><option value="bon" ${state.type==='bon'?'selected':''}>Bonuri</option><option value="pv" ${state.type==='pv'?'selected':''}>Procese-verbale</option></select><svg class="shop-fixed-assets-filter-chevron" viewBox="0 0 24 24"><path d="m7 10 5 5 5-5"/></svg></label><button type="button" id="shop-consumables-export"><span class="shop-fixed-assets-export-symbol">${icon('download')}</span><span class="shop-fixed-assets-export-copy"><strong>Exportă gestiunea</strong><small>PDF · Excel · ZIP complet</small></span><svg viewBox="0 0 24 24"><path d="m9 6 6 6-6 6"/></svg></button></div><div class="shop-fixed-assets-toolbar-footer"><div class="shop-fixed-assets-result-count">${icon('table')}<strong>${total?`${total} ${total===1?'poziție':'poziții'}`:'Niciun rezultat'}</strong>${total?`<span class="shop-fixed-assets-result-divider"></span><span>Se afișează ${first}–${last}</span>`:''}</div>${pagination(registry,'sus')}</div></section>`;}
  function tableRow(item,index,registry){
    const nr=(registry.page-1)*registry.page_size+index+1;
    const consumed=Number(item.consumed_quantity||0), remaining=Number(item.remaining_quantity||0);
    const count=Number(item.consumption_count||0);
    return `<tr><td><span class="shop-consumable-row-number">${nr}</span></td>
      <td>${esc(dateLabel(item.document_date))}</td>
      <td><span class="shop-fixed-asset-type ${esc(item.document_type)}">${esc(typeLabel(item.document_type))}</span></td>
      <td><strong>${esc(docNumber(item))}</strong></td>
      <td><strong>${esc(item.product_name)}</strong><small>Unitate: ${esc(item.unit||'buc')}</small></td>
      <td>${qty(item.quantity)}</td><td class="shop-consumable-consumed">${qty(consumed)}</td>
      <td><strong class="shop-consumable-stock ${remaining<=0?'empty':''}">${qty(remaining)}</strong></td>
      <td>${money(item.unit_price)}</td><td><strong>${money(item.total_value)}</strong></td>
      <td><div class="shop-consumable-consumption"><span>${count?`${count} ${count===1?'bon înregistrat':'bonuri înregistrate'}`:'Niciun bon emis'}</span>
        <button type="button" data-consumable-voucher="${esc(item.id)}" ${remaining<=0?'disabled title="Stocul disponibil este epuizat"':''}>${plusIcon()}<span>Bon de consum</span></button></div></td>
      <td><div class="shop-consumable-row-actions"><button type="button" data-consumable-detail="${esc(item.id)}">${icon('document')}<span>Deschide fișa</span><span aria-hidden="true">→</span></button>
        <button type="button" data-consumable-edit="${esc(item.id)}">Editează</button><button type="button" class="shop-fixed-asset-danger" data-consumable-delete="${esc(item.id)}">Șterge</button></div></td></tr>`;
  }

  async function load(page=state.page,options={}){const root=$('shop-consumables-content');if(!root)return;if(!options.quiet)root.innerHTML='<div class="shop-commerce-loading">Se încarcă gestiunea consumabilelor...</div>';try{state.page=page;const registry=await window.SHOP_API.listConsumables({page:state.page,page_size:state.pageSize,search:state.query,type:state.type});state.registry=registry;state.page=registry.page;render();}catch(error){root.innerHTML=`<div class="shop-commerce-error">${esc(error.message||'Gestiunea nu a putut fi încărcată.')}</div>`;}}
  function render(){const root=$('shop-consumables-content'),active=document.activeElement?.id==='shop-consumables-search'?{start:document.activeElement.selectionStart,end:document.activeElement.selectionEnd}:null,registry=state.registry||{items:[],total:0,page:1,page_size:state.pageSize,page_count:1};const rows=(registry.items||[]).map((item,index)=>tableRow(item,index,registry)).join('');const empty=`<section class="shop-fixed-assets-empty"><div class="shop-fixed-assets-empty-icon">${icon('archive')}</div><div class="shop-fixed-assets-empty-copy"><small>GESTIUNE CONSUMABILE</small><h2>Începe registrul consumabilelor</h2><p>Înregistrează documentele de intrare, apoi emite bonuri de consum care reduc automat stocul.</p></div><button type="button" id="shop-consumables-empty-add"><span>+</span><b>Înregistrează primul document</b></button></section>`;root.innerHTML=`${overview(registry,registry.items||[])}${toolbar(registry)}${rows?`<div class="shop-fixed-assets-register-title"><div><small>EVIDENȚĂ CONSUMABILE</small><h2>Registrul consumabilelor</h2></div><span>${registry.total} ${registry.total===1?'poziție':'poziții'}</span></div><div class="shop-fixed-assets-table-wrap shop-consumables-table-wrap"><table class="shop-fixed-assets-table shop-consumables-table"><thead><tr><th>Nr. crt.</th><th>Data doc.</th><th>Tip doc.</th><th>Serie/nr. doc.</th><th>Denumire consumabil</th><th>Cant. intrată</th><th>Consum</th><th>Stoc actual</th><th>Preț unitar</th><th>Valoare totală</th><th>Bon de consum</th><th>Detalii</th></tr></thead><tbody>${rows}</tbody></table></div>${pagination(registry,'jos')}`:empty}`;wireTable();if(active){const search=$('shop-consumables-search');search?.focus();search?.setSelectionRange(active.start,active.end);}}
  function wireTable(){const search=$('shop-consumables-search');search?.addEventListener('input',event=>{state.query=event.target.value;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>{state.page=1;void load(1,{quiet:true});},260);});$('shop-consumables-type')?.addEventListener('change',event=>{state.type=event.target.value;state.page=1;void load(1);});$('shop-consumables-export')?.addEventListener('click',openExport);$('shop-consumables-empty-add')?.addEventListener('click',openCreate);document.querySelectorAll('[data-consumables-page]').forEach(button=>button.addEventListener('click',()=>void load(Number(button.dataset.consumablesPage))));document.querySelectorAll('[data-consumables-page-input]').forEach(input=>input.addEventListener('change',()=>void load(Math.max(1,Math.min(Number(state.registry.page_count),Number(input.value||1))))));rootAll('[data-consumable-detail]').forEach(button=>button.addEventListener('click',()=>void openDetail(button.dataset.consumableDetail)));rootAll('[data-consumable-edit]').forEach(button=>button.addEventListener('click',()=>void openEdit(button.dataset.consumableEdit)));rootAll('[data-consumable-delete]').forEach(button=>button.addEventListener('click',()=>void askDeleteItem(button.dataset.consumableDelete)));rootAll('[data-consumable-voucher]').forEach(button=>button.addEventListener('click',()=>void openVoucherForItem(button.dataset.consumableVoucher)));}
  const rootAll=selector=>Array.from($('shop-consumables-content')?.querySelectorAll(selector)||[]);

  function newLine(){return {id:'',product_name:'',unit:'buc',quantity:1,unit_price:0,vat_rate:21,vat_value:'',vat_manual:false};}
  function openCreate(){state.editingDocument=null;state.lines=[newLine()];state.files=[];$('shop-consumable-create-form').reset();$('shop-consumable-document-date').value=today();$('shop-consumable-editor-title').textContent='Înregistrează un document';$('shop-consumable-save').querySelector('span').textContent='Înregistrează documentul';$('shop-consumable-delete-document').hidden=true;renderLines();renderFiles();open('shop-consumable-create-modal');}
  function renderLines(){const root=$('shop-consumable-lines');root.innerHTML=state.lines.map((line,index)=>{const net=Number(line.quantity||0)*Number(line.unit_price||0),vat=line.vat_manual?Number(line.vat_value||0):net*Number(line.vat_rate||0)/100,total=net+vat;return `<article class="shop-fixed-asset-line" data-consumable-line="${index}"><header><span>${String(index+1).padStart(2,'0')}</span><strong>Poziție document</strong><button type="button" data-consumable-line-remove="${index}" aria-label="Șterge poziția">×</button></header><div class="shop-fixed-asset-line-fields"><label class="wide">Denumire consumabil *<input data-consumable-field="product_name" value="${esc(line.product_name)}" maxlength="500" required></label><label>U.M.<input data-consumable-field="unit" value="${esc(line.unit||'buc')}" maxlength="40" required></label><label>Cantitate *<input data-consumable-field="quantity" type="number" min="0.0001" step="0.0001" value="${esc(line.quantity)}" required></label><label>Preț unitar *<input data-consumable-field="unit_price" type="number" min="0" step="0.0001" value="${esc(line.unit_price)}" required></label><label>Cotă TVA % *<input data-consumable-field="vat_rate" type="number" min="0" max="100" step="0.01" value="${esc(line.vat_rate)}" required></label><label>Valoare TVA<input data-consumable-field="vat_value" type="number" min="0" step="0.01" value="${esc(vat.toFixed(2))}"><small>Editabilă manual</small></label><div class="shop-fixed-asset-line-total"><small>TOTAL POZIȚIE</small><strong>${money(total)}</strong><span>Fără TVA ${money(net)}</span></div></div></article>`;}).join('');root.querySelectorAll('[data-consumable-field]').forEach(input=>{const numeric=['quantity','unit_price','vat_rate','vat_value'].includes(input.dataset.consumableField);input.addEventListener(numeric?'change':'input',()=>{const index=Number(input.closest('[data-consumable-line]').dataset.consumableLine),field=input.dataset.consumableField;state.lines[index][field]=input.value;if(field==='vat_value')state.lines[index].vat_manual=true;if(numeric)renderLines();});});root.querySelectorAll('[data-consumable-line-remove]').forEach(button=>button.addEventListener('click',()=>{if(state.lines.length===1)return toast('Documentul trebuie să aibă cel puțin o poziție.','error');state.lines.splice(Number(button.dataset.consumableLineRemove),1);renderLines();}));}
  function renderFiles(){const root=$('shop-consumable-pending-files');const stored=state.editingDocument?.files||[];root.innerHTML=stored.map(file=>`<div><span>${icon('document')}</span><strong>${esc(file.original_name)}<small>Fișier salvat · ${Math.max(1,Math.round(Number(file.file_size)/1024))} KB</small></strong></div>`).join('')+state.files.map((file,index)=>`<div><span>${icon('document')}</span><strong>${esc(file.name)}<small>Pregătit · ${Math.max(1,Math.round(file.size/1024))} KB</small></strong><button type="button" data-consumable-pending-remove="${index}">×</button></div>`).join('');root.querySelectorAll('[data-consumable-pending-remove]').forEach(button=>button.addEventListener('click',()=>{state.files.splice(Number(button.dataset.consumablePendingRemove),1);renderFiles();}));}
  async function saveDocument(event){event.preventDefault();const button=$('shop-consumable-save');if(button.disabled)return;button.disabled=true;try{const attachments=await Promise.all(state.files.map(filePayload));const payload={document:{document_date:$('shop-consumable-document-date').value,document_type:$('shop-consumable-document-type').value,series:$('shop-consumable-series').value,document_number:$('shop-consumable-number').value,notes:$('shop-consumable-notes').value},lines:state.lines.map(line=>({...line,vat_value:line.vat_manual?line.vat_value:null})),attachments,revision:state.editingDocument?.revision};if(state.editingDocument)await window.SHOP_API.updateConsumableDocument(state.editingDocument.id,payload);else await window.SHOP_API.createConsumableDocument(payload);close('shop-consumable-create-modal');await load(1);toast(state.editingDocument?'Documentul a fost actualizat și stocul recalculat.':'Documentul și consumabilele au intrat în gestiune.');}catch(error){toast(error.message||'Documentul nu a putut fi salvat.','error');}finally{button.disabled=false;}}
  async function openEdit(id){try{const item=await window.SHOP_API.getConsumable(id),document=await window.SHOP_API.getConsumableDocument(item.document_id);state.editingDocument=document;state.lines=document.lines.map(line=>({...line,vat_manual:Boolean(Number(line.vat_manual))}));state.files=[];$('shop-consumable-create-form').reset();$('shop-consumable-document-date').value=document.document_date;$('shop-consumable-document-type').value=document.document_type;$('shop-consumable-series').value=document.series||'';$('shop-consumable-number').value=document.document_number;$('shop-consumable-notes').value=document.notes||'';$('shop-consumable-editor-title').textContent=`Editează documentul ${docNumber(document)}`;$('shop-consumable-save').querySelector('span').textContent='Salvează modificările';$('shop-consumable-delete-document').hidden=false;renderLines();renderFiles();open('shop-consumable-create-modal');}catch(error){toast(error.message||'Documentul nu a putut fi deschis.','error');}}

  function confirm(title,text,task){state.deleteTask=task;$('shop-consumable-confirm-title').textContent=title;$('shop-consumable-confirm-text').textContent=text;$('shop-consumable-confirm-error').hidden=true;open('shop-consumable-confirm-modal');}
  async function runConfirm(){const button=$('shop-consumable-confirm-submit');if(button.disabled||!state.deleteTask)return;button.disabled=true;try{await state.deleteTask();state.deleteTask=null;close('shop-consumable-confirm-modal');}catch(error){$('shop-consumable-confirm-error').textContent=error.message||'Operațiunea nu a putut fi efectuată.';$('shop-consumable-confirm-error').hidden=false;}finally{button.disabled=false;}}
  async function askDeleteItem(id){try{const item=await window.SHOP_API.getConsumable(id);confirm('Șterge consumabilul',`Ștergi „${item.product_name}”? Pozițiile sale din bonurile de consum vor fi eliminate, bonurile rămase fără poziții vor fi șterse, iar stocul se recalculează. Operațiunea nu poate fi anulată.`,async()=>{await window.SHOP_API.deleteConsumable(id,item.revision);close('shop-consumable-detail-modal');await load();toast('Consumabilul a fost șters și gestiunea a fost recalculată.');});}catch(error){toast(error.message,'error');}}
  function askDeleteDocument(){const document=state.editingDocument;if(!document)return;const vouchers=document.lines.reduce((total,line)=>total+Number(line.vouchers?.length||0),0);confirm('Șterge întregul document',`Ștergi documentul ${docNumber(document)}, cele ${document.lines.length} poziții, ${vouchers} legături cu bonuri și toate fișierele atașate? Bonurile rămase fără poziții vor fi șterse.`,async()=>{await window.SHOP_API.deleteConsumableDocument(document.id,document.revision);close('shop-consumable-create-modal');close('shop-consumable-detail-modal');await load(1);toast('Documentul și pozițiile sale au fost șterse.');});}

  function documentsMarkup(item){const files=item.files||[];return `<section class="shop-fixed-asset-documents"><header><div><small>DOCUMENTE JUSTIFICATIVE</small><strong>${files.length} fișiere atașate</strong></div><button type="button" id="shop-consumable-files-add">+ Adaugă fișiere</button><input type="file" id="shop-consumable-files-input" multiple accept=".pdf,.jpg,.jpeg,.png,.webp,.xls,.xlsx,.doc,.docx,.xml" hidden></header><div class="shop-fixed-asset-file-list">${files.map(file=>`<div><span>${icon('document')}</span><strong>${esc(file.original_name)}<small>${esc(String(file.extension||'').toUpperCase())} · ${Math.max(1,Math.round(Number(file.file_size)/1024))} KB</small></strong><div class="shop-fixed-asset-file-actions"><button type="button" data-consumable-file-view="${esc(file.id)}">Vezi</button><button type="button" data-consumable-file-download="${esc(file.id)}">Descarcă</button><button type="button" class="shop-fixed-asset-danger" data-consumable-file-delete="${esc(file.id)}">Șterge</button></div></div>`).join('')||'<p>Nu există fișiere atașate.</p>'}</div></section>`;}
  async function openDetail(id){open('shop-consumable-detail-modal');$('shop-consumable-detail-content').innerHTML='<div class="shop-commerce-loading">Se încarcă fișa...</div>';try{const item=await window.SHOP_API.getConsumable(id);state.selected=item;$('shop-consumable-detail-title').textContent=item.product_name;const history=(item.vouchers||[]).map(v=>`<tr><td>${esc(dateLabel(v.voucher_date))}</td><td><strong>${esc(voucherNumber(v))}</strong></td><td>${qty(v.quantity)} ${esc(item.unit)}</td><td>${esc(v.giver_name)} → ${esc(v.receiver_name)}</td><td>${money(v.value)}</td><td><div class="shop-fixed-asset-history-actions"><button type="button" class="shop-voucher-pdf" data-consumption-export-id="${esc(v.voucher_id)}" data-consumption-export-format="pdf">PDF</button><button type="button" class="shop-voucher-xlsx" data-consumption-export-id="${esc(v.voucher_id)}" data-consumption-export-format="xlsx">Excel</button><button type="button" data-consumption-voucher-edit="${esc(v.voucher_id)}">Editează</button><button type="button" class="shop-fixed-asset-danger" data-consumption-voucher-delete="${esc(v.voucher_id)}">Șterge</button></div></td></tr>`).join('');$('shop-consumable-detail-content').innerHTML=`<section class="shop-fixed-asset-detail-hero"><span>${icon('archive')}</span><div><small>${esc(typeLabel(item.document_type))} · ${esc(docNumber(item))}</small><h3>${esc(item.product_name)}</h3><p>Document din ${esc(dateLabel(item.document_date))}</p></div><b>${qty(item.remaining_quantity)}<small>STOC ACTUAL</small></b></section><section class="shop-fixed-asset-detail-grid"><article><small>CANTITATE INTRATĂ</small><strong>${qty(item.quantity)} ${esc(item.unit)}</strong></article><article><small>CANTITATE CONSUMATĂ</small><strong>${qty(item.consumed_quantity)}</strong></article><article><small>PREȚ UNITAR</small><strong>${money(item.unit_price)}</strong></article><article><small>TVA ${qty(item.vat_rate)}%</small><strong>${money(item.vat_value)}</strong></article><article class="total"><small>VALOARE TOTALĂ</small><strong>${money(item.total_value)}</strong></article></section>${documentsMarkup(item)}<section class="shop-fixed-asset-disposal-history"><header><div><small>ISTORIC BONURI DE CONSUM</small><strong>${item.vouchers.length} înregistrări</strong></div><button type="button" data-consumable-detail-voucher="${esc(item.id)}" ${Number(item.remaining_quantity)<=0?'disabled':''}>+ Bon de consum</button></header>${history?`<table><thead><tr><th>Data</th><th>Bon</th><th>Cantitate</th><th>Predător / primitor</th><th>Valoare</th><th>Acțiuni</th></tr></thead><tbody>${history}</tbody></table>`:'<p>Nu există bonuri de consum pentru această poziție.</p>'}</section><section class="shop-fixed-asset-preview" id="shop-consumable-preview" hidden></section>`;wireDetail(item);}catch(error){$('shop-consumable-detail-content').innerHTML=`<div class="shop-commerce-error">${esc(error.message||'Fișa nu a putut fi încărcată.')}</div>`;}}
  function wireDetail(item){const root=$('shop-consumable-detail-content');root.querySelectorAll('[data-consumption-export-id]').forEach(button=>button.addEventListener('click',()=>void downloadVoucher(button.dataset.consumptionExportId,button.dataset.consumptionExportFormat,button)));root.querySelector('[data-consumable-detail-voucher]')?.addEventListener('click',()=>void openVoucherForItem(item.id));root.querySelectorAll('[data-consumption-voucher-edit]').forEach(button=>button.addEventListener('click',()=>void openVoucher(button.dataset.consumptionVoucherEdit)));root.querySelectorAll('[data-consumption-voucher-delete]').forEach(button=>button.addEventListener('click',()=>void askDeleteVoucher(button.dataset.consumptionVoucherDelete,item.id)));$('shop-consumable-files-add')?.addEventListener('click',()=>$('shop-consumable-files-input').click());$('shop-consumable-files-input')?.addEventListener('change',async event=>{const files=Array.from(event.target.files||[]);if(!files.length)return;try{await window.SHOP_API.addConsumableFiles(item.document_id,await Promise.all(files.map(filePayload)));await openDetail(item.id);toast('Fișierele au fost adăugate.');}catch(error){toast(error.message,'error');}});root.querySelectorAll('[data-consumable-file-view]').forEach(button=>button.addEventListener('click',()=>void downloadDocument(true,button.dataset.consumableFileView)));root.querySelectorAll('[data-consumable-file-download]').forEach(button=>button.addEventListener('click',()=>void downloadDocument(false,button.dataset.consumableFileDownload)));root.querySelectorAll('[data-consumable-file-delete]').forEach(button=>button.addEventListener('click',()=>{const file=item.files.find(f=>f.id===button.dataset.consumableFileDelete);confirm('Șterge fișierul',`Ștergi „${file.original_name}”?`,async()=>{await window.SHOP_API.deleteConsumableFile(item.document_id,file.id);await openDetail(item.id);toast('Fișierul a fost șters.');});}));}
  function markVoucherDirty(){if(!state.voucher)return;state.voucherDirty=true;$('shop-consumption-export-hint').textContent='Salvează modificările înainte de descărcare.';}
  async function downloadVoucher(id,format,button){
    if(!id||button?.disabled)return;
    if(!button?.dataset.consumptionExportId&&state.voucherDirty)return toast('Salvează modificările bonului înainte de descărcare.','error');
    if(button)button.disabled=true;
    try{saveDownload(await window.SHOP_API.exportConsumptionVoucher(id,format));toast(`Bonul de consum a fost descărcat în ${format==='pdf'?'PDF':'Excel'}.`);}
    catch(error){toast(error.message||'Bonul nu a putut fi descărcat.','error');}
    finally{if(button)button.disabled=false;}
  }
  async function downloadDocument(preview,fileId=''){const item=state.selected;if(!item)return;try{const file=await window.SHOP_API.downloadConsumableDocument(item.document_id,fileId);if(!preview){saveDownload(file);return;}const bytes=Uint8Array.from(atob(file.content_base64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:file.mime_type}));if(state.previewUrl)URL.revokeObjectURL(state.previewUrl);state.previewUrl=url;const root=$('shop-consumable-preview');root.hidden=false;root.innerHTML=String(file.mime_type).startsWith('image/')?`<img src="${url}" alt="${esc(file.file_name)}">`:file.mime_type==='application/pdf'?`<iframe src="${url}" title="${esc(file.file_name)}"></iframe>`:'<p>Acest fișier poate fi doar descărcat.</p>';root.scrollIntoView({behavior:'smooth'});}catch(error){toast(error.message,'error');}}

  async function loadVoucherContext(){const [meta,candidates]=await Promise.all([window.SHOP_API.getConsumptionVoucherMeta('BC'),window.SHOP_API.listConsumables({page:1,page_size:500})]);state.voucherMeta=meta;state.people=meta.people;state.voucherCandidates=candidates.items||[];}
  async function openVoucherForItem(id){try{await loadVoucherContext();const item=await window.SHOP_API.getConsumable(id);state.voucher=null;state.voucherLines=[{consumable_id:id,quantity:item.remaining_quantity}];prepareVoucherForm();$('shop-consumption-voucher-number').value=state.voucherMeta.next_number;renderVoucherLines();open('shop-consumption-voucher-modal');}catch(error){toast(error.message||'Bonul nu a putut fi pregătit.','error');}}
  async function openVoucher(id){try{await loadVoucherContext();const voucher=await window.SHOP_API.getConsumptionVoucher(id);state.voucher=voucher;state.voucherLines=voucher.lines.map(line=>({consumable_id:line.consumable_id,quantity:line.quantity}));prepareVoucherForm(voucher);renderVoucherLines();open('shop-consumption-voucher-modal');}catch(error){toast(error.message||'Bonul nu a putut fi deschis.','error');}}
  function prepareVoucherForm(voucher=null){$('shop-consumption-voucher-form').reset();state.voucherDirty=false;$('shop-consumption-export-actions').hidden=!voucher;$('shop-consumption-export-hint').textContent='Versiunea salvată a bonului';$('shop-consumption-voucher-title').textContent=voucher?`Editează bonul ${voucherNumber(voucher)}`:'Bon de consum nou';$('shop-consumption-voucher-date').value=voucher?.voucher_date||today();$('shop-consumption-voucher-series').value=voucher?.series||'BC';$('shop-consumption-voucher-number').value=voucher?.voucher_number||'';$('shop-consumption-voucher-notes').value=voucher?.notes||'';$('shop-consumption-work-reference').value=voucher?.work_reference||'';$('shop-consumption-order-reference').value=voucher?.order_reference||'';$('shop-consumption-voucher-delete').hidden=!voucher;$('shop-consumption-voucher-save').textContent=voucher?'Salvează modificările':'Salvează bonul și scade stocul';renderPartySelects(voucher);}
  function renderPartySelects(voucher=null){for(const role of ['giver','receiver']){const select=$(`shop-consumption-${role}`),people=role==='giver'?state.people.givers:state.people.receivers;select.innerHTML='<option value="">Introduc manual…</option>'+people.filter(p=>Number(p.active)||p.id===voucher?.[`${role}_id`]).map(p=>`<option value="${esc(p.id)}" ${p.id===voucher?.[`${role}_id`]?'selected':''}>${esc(p.name)}${Number(p.active)?'':' (inactiv)'}</option>`).join('');$(`shop-consumption-${role}-name`).value=voucher?.[`${role}_name`]||'';}}
  function renderVoucherLines(){const root=$('shop-consumption-voucher-lines');root.innerHTML=state.voucherLines.map((line,index)=>{const current=state.voucherCandidates.find(item=>item.id===line.consumable_id);const options=state.voucherCandidates.filter(item=>Number(item.remaining_quantity)>0||item.id===line.consumable_id).map(item=>`<option value="${esc(item.id)}" ${item.id===line.consumable_id?'selected':''}>${esc(item.product_name)} · stoc ${qty(Number(item.remaining_quantity)+(state.voucher?.lines.find(old=>old.consumable_id===item.id)?.quantity||0))} ${esc(item.unit||'buc')}</option>`).join('');const available=Number(current?.remaining_quantity||0)+Number(state.voucher?.lines.find(old=>old.consumable_id===line.consumable_id)?.quantity||0);return `<div class="shop-consumption-voucher-line" data-voucher-line="${index}"><span>${String(index+1).padStart(2,'0')}</span><label>Consumabil *<select data-voucher-field="consumable_id" required><option value="">Alege consumabilul</option>${options}</select></label><label>Cantitate eliberată *<input data-voucher-field="quantity" type="number" min="0.0001" max="${available||0.0001}" step="0.0001" value="${esc(line.quantity)}" required><small>Disponibil: ${qty(available)} ${esc(current?.unit||'')}</small></label><button type="button" data-voucher-line-remove="${index}" aria-label="Elimină poziția">×</button></div>`;}).join('');root.querySelectorAll('[data-voucher-field]').forEach(input=>input.addEventListener('change',()=>{const index=Number(input.closest('[data-voucher-line]').dataset.voucherLine);state.voucherLines[index][input.dataset.voucherField]=input.value;renderVoucherLines();}));root.querySelectorAll('[data-voucher-line-remove]').forEach(button=>button.addEventListener('click',()=>{if(state.voucherLines.length===1)return toast('Bonul trebuie să conțină cel puțin o poziție.','error');state.voucherLines.splice(Number(button.dataset.voucherLineRemove),1);markVoucherDirty();renderVoucherLines();}));}
  async function saveVoucher(event){event.preventDefault();const button=$('shop-consumption-voucher-save');if(button.disabled)return;button.disabled=true;try{const payload={voucher_date:$('shop-consumption-voucher-date').value,series:$('shop-consumption-voucher-series').value,voucher_number:$('shop-consumption-voucher-number').value,giver_id:$('shop-consumption-giver').value,giver_name:$('shop-consumption-giver-name').value,receiver_id:$('shop-consumption-receiver').value,receiver_name:$('shop-consumption-receiver-name').value,notes:$('shop-consumption-voucher-notes').value,work_reference:$('shop-consumption-work-reference').value,order_reference:$('shop-consumption-order-reference').value,lines:state.voucherLines,revision:state.voucher?.revision};if(state.voucher)await window.SHOP_API.updateConsumptionVoucher(state.voucher.id,payload);else await window.SHOP_API.createConsumptionVoucher(payload);close('shop-consumption-voucher-modal');await load();if(state.selected?.id&&$('shop-consumable-detail-modal')?.classList.contains('visible'))await openDetail(state.selected.id);toast(state.voucher?'Bonul a fost actualizat și stocul recalculat.':'Bonul a fost emis, iar stocul a fost diminuat.');}catch(error){toast(error.message||'Bonul nu a putut fi salvat.','error');}finally{button.disabled=false;}}
  async function askDeleteVoucher(id,returnItem=state.selected?.id){try{const voucher=await window.SHOP_API.getConsumptionVoucher(id);confirm('Șterge bonul de consum',`Ștergi bonul ${voucherNumber(voucher)}? Toate cantitățile sale vor reveni automat în stoc.`,async()=>{await window.SHOP_API.deleteConsumptionVoucher(id,voucher.revision);close('shop-consumption-voucher-modal');await load();if(returnItem&&$('shop-consumable-detail-modal')?.classList.contains('visible'))await openDetail(returnItem);toast('Bonul a fost șters și stocul a fost refăcut.');});}catch(error){toast(error.message,'error');}}

  function openPeople(role){state.personRole=role;state.personEditing=null;renderPeople();open('shop-consumable-people-modal');}
  function resetPerson(){state.personEditing=null;$('shop-consumable-person-form').reset();$('shop-consumable-person-id').value='';$('shop-consumable-person-active').checked=true;}
  function renderPeople(){document.querySelectorAll('[data-people-role]').forEach(button=>button.classList.toggle('active',button.dataset.peopleRole===state.personRole));$('shop-consumable-people-title').textContent=state.personRole==='giver'?'Predători și gestionari':'Primitori';const people=state.personRole==='giver'?state.people.givers:state.people.receivers;$('shop-consumable-people-list').innerHTML=people.map(person=>`<article class="${Number(person.active)?'':'inactive'}"><span>${icon('users')}</span><div><strong>${esc(person.name)}</strong><small>${esc(person.details||'Fără detalii')}${Number(person.active)?'':' · INACTIV'}</small></div><button type="button" data-person-edit="${esc(person.id)}">Editează</button><button type="button" class="shop-fixed-asset-danger" data-person-delete="${esc(person.id)}">Șterge</button></article>`).join('')||'<p>Nu există persoane în această listă.</p>';$('shop-consumable-people-list').querySelectorAll('[data-person-edit]').forEach(button=>button.addEventListener('click',()=>{const person=people.find(p=>p.id===button.dataset.personEdit);state.personEditing=person;$('shop-consumable-person-id').value=person.id;$('shop-consumable-person-name').value=person.name;$('shop-consumable-person-details').value=person.details||'';$('shop-consumable-person-active').checked=Boolean(Number(person.active));}));$('shop-consumable-people-list').querySelectorAll('[data-person-delete]').forEach(button=>button.addEventListener('click',()=>{const person=people.find(p=>p.id===button.dataset.personDelete);confirm('Șterge persoana',`Ștergi „${person.name}” din listă? Bonurile deja emise păstrează numele istoric.`,async()=>{state.people=await window.SHOP_API.deleteConsumablePerson(person.id);renderPartySelects(state.voucher);renderPeople();toast('Persoana a fost eliminată din listă.');});}));resetPerson();}
  async function savePerson(event){event.preventDefault();try{state.people=await window.SHOP_API.saveConsumablePerson({id:$('shop-consumable-person-id').value,role:state.personRole,name:$('shop-consumable-person-name').value,details:$('shop-consumable-person-details').value,active:$('shop-consumable-person-active').checked});renderPartySelects(state.voucher);renderPeople();toast('Persoana a fost salvată.');}catch(error){toast(error.message,'error');}}

  function periodRange(kind){const now=new Date(`${today()}T12:00:00`),fmt=date=>date.toLocaleDateString('sv-SE',{timeZone:'Europe/Bucharest'}),first=new Date(now.getFullYear(),now.getMonth(),1);if(kind==='all')return['',''];if(kind==='year')return[`${now.getFullYear()}-01-01`,fmt(now)];if(kind==='current_month')return[fmt(first),fmt(now)];if(kind==='last_month')return[fmt(new Date(now.getFullYear(),now.getMonth()-1,1)),fmt(new Date(now.getFullYear(),now.getMonth(),0))];if(kind==='six_months')return[fmt(new Date(now.getFullYear(),now.getMonth()-5,1)),fmt(now)];if(kind==='three_months')return[fmt(new Date(now.getFullYear(),now.getMonth()-2,1)),fmt(now)];return[$('shop-consumables-export-from')?.value||'',$('shop-consumables-export-to')?.value||''];}
  function openExport(){state.exportFormat='xlsx';state.exportPeriod='current_month';const [from,to]=periodRange('current_month');$('shop-consumables-export-from').value=from;$('shop-consumables-export-to').value=to;updateExport();open('shop-consumables-export-modal');}
  function updateExport(){document.querySelectorAll('[data-consumables-format]').forEach(button=>button.classList.toggle('active',button.dataset.consumablesFormat===state.exportFormat));document.querySelectorAll('[data-consumables-period]').forEach(button=>button.classList.toggle('active',button.dataset.consumablesPeriod===state.exportPeriod));$('shop-consumables-export-custom').hidden=state.exportPeriod!=='custom';const [from,to]=periodRange(state.exportPeriod),label={pdf:'PDF',xlsx:'Excel cu două foi',zip:'ZIP cu PDF, Excel și documente'}[state.exportFormat];$('shop-consumables-export-summary').textContent=label;$('shop-consumables-export-range').textContent=from||to?`${from?dateLabel(from):'Început'} – ${to?dateLabel(to):'Prezent'}`:'Toată perioada';const button=$('shop-consumables-export-confirm');button.disabled=state.exportBusy;button.querySelector('span').textContent=state.exportBusy?'Se pregătește exportul…':`Descarcă ${state.exportFormat==='xlsx'?'Excel':state.exportFormat.toUpperCase()}`;}
  async function exportData(event){event.preventDefault();if(state.exportBusy)return;const [from,to]=periodRange(state.exportPeriod);if(state.exportPeriod==='custom'&&(!from||!to||from>to))return toast('Alege o perioadă custom validă.','error');state.exportBusy=true;updateExport();try{saveDownload(await window.SHOP_API.exportConsumables(state.exportFormat,from,to));close('shop-consumables-export-modal');toast('Exportul consumabilelor a fost generat.');}catch(error){toast(error.message||'Exportul nu a putut fi generat.','error');}finally{state.exportBusy=false;updateExport();}}

  function init(){
    $('shop-consumables-refresh')?.addEventListener('click',()=>void load(state.page));$('shop-consumables-add')?.addEventListener('click',openCreate);
    document.querySelectorAll('[data-consumables-close]').forEach(button=>button.addEventListener('click',()=>close(button.dataset.consumablesClose)));
    document.querySelectorAll('#shop-consumable-create-modal,#shop-consumable-detail-modal,#shop-consumption-voucher-modal,#shop-consumable-people-modal,#shop-consumable-confirm-modal,#shop-consumables-export-modal').forEach(overlay=>overlay.addEventListener('mousedown',event=>{if(event.target===overlay)close(overlay.id);}));
    $('shop-consumable-create-form')?.addEventListener('submit',saveDocument);$('shop-consumable-add-line')?.addEventListener('click',()=>{state.lines.push(newLine());renderLines();});$('shop-consumable-file-pick')?.addEventListener('click',()=>$('shop-consumable-file-input').click());$('shop-consumable-file-input')?.addEventListener('change',event=>{state.files.push(...Array.from(event.target.files||[]));event.target.value='';renderFiles();});$('shop-consumable-delete-document')?.addEventListener('click',askDeleteDocument);$('shop-consumable-edit')?.addEventListener('click',()=>void openEdit(state.selected?.id));$('shop-consumable-delete')?.addEventListener('click',()=>void askDeleteItem(state.selected?.id));$('shop-consumable-confirm-submit')?.addEventListener('click',runConfirm);
    $('shop-consumption-voucher-form')?.addEventListener('input',markVoucherDirty);
    $('shop-consumption-voucher-form')?.addEventListener('change',markVoucherDirty);
    $('shop-consumption-export-actions')?.querySelectorAll('[data-consumption-export-format]').forEach(button=>button.addEventListener('click',()=>void downloadVoucher(state.voucher?.id,button.dataset.consumptionExportFormat,button)));
    $('shop-consumption-voucher-form')?.addEventListener('submit',saveVoucher);$('shop-consumption-add-line')?.addEventListener('click',()=>{state.voucherLines.push({consumable_id:'',quantity:1});markVoucherDirty();renderVoucherLines();});$('shop-consumption-voucher-delete')?.addEventListener('click',()=>void askDeleteVoucher(state.voucher?.id));$('shop-consumption-voucher-series')?.addEventListener('change',async event=>{if(state.voucher)return;try{state.voucherMeta=await window.SHOP_API.getConsumptionVoucherMeta(event.target.value);$('shop-consumption-voucher-number').value=state.voucherMeta.next_number;}catch{}});document.querySelectorAll('[data-manage-consumable-people]').forEach(button=>button.addEventListener('click',()=>openPeople(button.dataset.manageConsumablePeople)));
    document.querySelectorAll('[data-people-role]').forEach(button=>button.addEventListener('click',()=>{state.personRole=button.dataset.peopleRole;renderPeople();}));$('shop-consumable-person-form')?.addEventListener('submit',savePerson);$('shop-consumable-person-reset')?.addEventListener('click',resetPerson);
    $('shop-consumables-export-form')?.addEventListener('submit',exportData);document.querySelectorAll('[data-consumables-format]').forEach(button=>button.addEventListener('click',()=>{state.exportFormat=button.dataset.consumablesFormat;updateExport();}));document.querySelectorAll('[data-consumables-period]').forEach(button=>button.addEventListener('click',()=>{state.exportPeriod=button.dataset.consumablesPeriod;updateExport();}));['shop-consumables-export-from','shop-consumables-export-to'].forEach(id=>$(id)?.addEventListener('change',updateExport));
  }

  window.GTrotsConsumables={page,modals,init,load,openCreate};
})();
